#include FENWICK_SOURCE
#include <chrono>
#include <cstdio>
#include <random>
#include <string>
using Clock=std::chrono::steady_clock;
std::int64_t since(Clock::time_point t){return std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-t).count();}
int main(int argc,char**argv){
 std::string name=argc>1?argv[1]:"random";std::uint64_t n=500000;int count=100000,queries=100000;
 if(name=="small"){n=32;count=100000;}
 if(name=="border"){n=65;count=100000;}
 if(name=="dense"){n=4096;count=100000;}
 if(name=="sparse"){n=1000000007;count=10000;queries=20000;}
 if(name=="huge"){n=UINT64_MAX;count=2000;queries=4000;}
 if(argc>2){count*=10;queries*=4;}
 std::mt19937_64 gen(986);std::vector<std::uint64_t> pos(count),ls(queries),rs(queries);
 for(auto&k:pos)k=gen()%n;for(int i=0;i<queries;++i){ls[i]=gen()%n;rs[i]=gen()%n;if(ls[i]>rs[i])std::swap(ls[i],rs[i]);}
 DynamicFenwickTree<std::uint64_t,std::int64_t> bit(n);std::uint64_t sum=0;auto t=Clock::now();for(int i=0;i<count;++i)bit.add(pos[i],i%7);auto add=since(t);const auto nodes=bit.stored_nodes();
 t=Clock::now();for(int i=0;i<queries;++i)sum+=bit.sum(ls[i],rs[i]);auto range=since(t);
 t=Clock::now();for(int i=0;i<queries;++i)sum+=bit.sum(rs[i]);auto prefix=since(t);
 t=Clock::now();for(int i=0;i<count;++i)sum+=bit.get(pos[i]);auto get=since(t);
 t=Clock::now();for(int i=0;i<count;++i)bit.set(pos[i],i%9);auto set=since(t);
 std::vector<std::int64_t> weights(queries);const auto total=bit.sum_all();for(auto& w:weights)w=static_cast<std::int64_t>(gen()%static_cast<std::uint64_t>(total+1));
 t=Clock::now();for(int i=0;i<queries;++i){sum+=bit.lower_bound(weights[i]);sum+=bit.upper_bound(weights[i]);}auto search=since(t);
 t=Clock::now();auto clone=bit;auto copy=since(t);sum+=clone.sum_all();
 t=Clock::now();bit.clear();auto clear=since(t);
 t=Clock::now();for(int i=0;i<count;++i)bit.add(pos[i],i%7);auto refill=since(t);sum+=bit.sum_all();
 std::printf("{\"case\":\"%s\",\"add\":%jd,\"range\":%jd,\"prefix\":%jd,\"get\":%jd,\"set\":%jd,\"search\":%jd,\"copy\":%jd,\"clear\":%jd,\"refill\":%jd,\"nodes\":%zu,\"sum\":%ju}\n",name.c_str(),(std::intmax_t)add,(std::intmax_t)range,(std::intmax_t)prefix,(std::intmax_t)get,(std::intmax_t)set,(std::intmax_t)search,(std::intmax_t)copy,(std::intmax_t)clear,(std::intmax_t)refill,nodes,(std::uintmax_t)sum);
}
